<?php
namespace App\Policies;
use App\Enums\DocumentVisibility;use App\Enums\UserRole;use App\Models\Document;use App\Models\User;
class DocumentPolicy { public function view(User $user,Document $document):bool { if($user->isSuperAdmin())return true;if($user->role===UserRole::MANAGER)return $user->company_id===$document->company_id;if($user->role===UserRole::CONSULTANT)return $user->company_id===$document->company_id && $user->hasPermission('documents.view') && $document->visibility!==DocumentVisibility::MANAGER_ONLY;if($user->role===UserRole::PATIENT)return $user->patientProfile?->id===$document->patient_id && $document->visibility===DocumentVisibility::PATIENT_VISIBLE;return false;} public function create(User $user):bool{return $user->hasPermission('documents.create');} public function delete(User $user,Document $document):bool{return $user->isSuperAdmin()||($user->role===UserRole::MANAGER&&$user->company_id===$document->company_id)||($user->role===UserRole::CONSULTANT&&$user->company_id===$document->company_id&&$user->hasPermission('documents.delete'));} }
